// Package tokens is the Go port of the EMBER token format (design.md §4.1-4.3)
// and of the per-token baselines (design.md §5) used by the E8 prototype and
// by the E3b HPACK measurement.
//
// Normative format: paper/experiments/tests/vectors.json (generated by the Python reference,
// experiments/ember).  Merkle tree: pairwise with promotion of an unpaired last node (no sibling
// is emitted for a promoted node); level l+1 node j = Th(tweak(kid,e,NODE,l+1,j,0), left||right).
// Root R = top node (N=1: the leaf).
package tokens

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/ecdsa"
	"crypto/ed25519"
	"crypto/elliptic"
	"crypto/hmac"
	"crypto/mlkem"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"fmt"
	"math/big"
	"strconv"
	"strings"

	"github.com/cloudflare/circl/sign/mldsa/mldsa44"
	"github.com/cloudflare/circl/sign/mldsa/mldsa65"
)

var B64 = base64.RawURLEncoding

// ---------------------------------------------------------------- hashing

var CTX = []byte("EMBERv1\x00")

const (
	TypeLeaf   = 0
	TypeNode   = 1
	TypeRoot   = 2
	TypePeriod = 3
)

const TweakLen = 26

// Tweak returns the 26-byte tweak ctx(8)|kid(4)|epoch(4)|type(1)|level(1)|index(4)|tenant(4).
func Tweak(kid, epoch uint32, typ, level uint8, index, tenant uint32) []byte {
	t := make([]byte, TweakLen)
	copy(t, CTX)
	binary.BigEndian.PutUint32(t[8:], kid)
	binary.BigEndian.PutUint32(t[12:], epoch)
	t[16] = typ
	t[17] = level
	binary.BigEndian.PutUint32(t[18:], index)
	binary.BigEndian.PutUint32(t[22:], tenant)
	return t
}

// Th(tw, data) = trunc_n(SHA-256(tw || data)).
func Th(tw, data []byte, n int) []byte {
	h := sha256.New()
	h.Write(tw)
	h.Write(data)
	return h.Sum(nil)[:n]
}

// thInto is an allocation-light Th for the verification hot path.
func thInto(dst *[32]byte, tw *[TweakLen]byte, a, b []byte) {
	h := sha256.New()
	h.Write(tw[:])
	h.Write(a)
	h.Write(b)
	h.Sum(dst[:0])
}

func LeafHash(kid, epoch, idx, tenant uint32, r, enc []byte, n int) []byte {
	return Th(Tweak(kid, epoch, TypeLeaf, 0, idx, tenant), append(append([]byte{}, r...), enc...), n)
}

// BuildTree returns the root and all levels (levels[0] = leaves).
func BuildTree(kid, epoch uint32, leaves [][]byte, n int) ([]byte, [][][]byte) {
	levels := [][][]byte{leaves}
	cur := leaves
	lvl := uint8(0)
	for len(cur) > 1 {
		next := make([][]byte, (len(cur)+1)/2)
		for j := range next {
			if 2*j+1 < len(cur) {
				buf := make([]byte, 0, 2*n)
				buf = append(buf, cur[2*j]...)
				buf = append(buf, cur[2*j+1]...)
				next[j] = Th(Tweak(kid, epoch, TypeNode, lvl+1, uint32(j), 0), buf, n)
			} else {
				next[j] = cur[2*j]
			}
		}
		levels = append(levels, next)
		cur = next
		lvl++
	}
	return cur[0], levels
}

// AuthPath: siblings bottom-up; promoted nodes contribute no sibling.
func AuthPath(levels [][][]byte, i int) [][]byte {
	var path [][]byte
	k := i
	for l := 0; l < len(levels)-1; l++ {
		s := len(levels[l])
		if k^1 < s {
			path = append(path, levels[l][k^1])
		}
		k >>= 1
	}
	return path
}

// RootFromPath recomputes the root from leaf, index, N and the path (flattened n-byte nodes).
func RootFromPath(kid, epoch, i, N uint32, leaf, path []byte, n int) ([]byte, error) {
	if i >= N {
		return nil, errors.New("idx>=N")
	}
	var x [32]byte
	copy(x[:], leaf)
	var tw [TweakLen]byte
	copy(tw[:], Tweak(kid, epoch, TypeNode, 0, 0, 0))
	k, s, p := i, N, 0
	lvl := uint8(0)
	for s > 1 {
		if k^1 < s {
			if p+n > len(path) {
				return nil, errors.New("path too short")
			}
			sib := path[p : p+n]
			p += n
			tw[17] = lvl + 1
			binary.BigEndian.PutUint32(tw[18:], k>>1)
			if k&1 == 1 {
				thInto(&x, &tw, sib, x[:n])
			} else {
				var xc [32]byte
				copy(xc[:], x[:n])
				thInto(&x, &tw, xc[:n], sib)
			}
		}
		k >>= 1
		s = (s + 1) / 2
		lvl++
	}
	if p != len(path) {
		return nil, errors.New("path length mismatch")
	}
	return x[:n], nil
}

// ---------------------------------------------------------------- claims

type Claims struct {
	URLPrefix string
	Expires   int64
	Tenant    uint32
	IP        string
}

func (c Claims) Enc() string {
	s := "URLPrefix=" + B64.EncodeToString([]byte(c.URLPrefix)) + ":Expires=" + strconv.FormatInt(c.Expires, 10) +
		":Tenant=" + strconv.FormatUint(uint64(c.Tenant), 10)
	if c.IP != "" {
		s += ":IP=" + c.IP
	}
	return s
}

// SplitToken splits "<claims>:<Field>=<v>..." into claims part, and map of trailing auth fields.
// The claims part ends before the first field that is not URLPrefix/Expires/Tenant/IP.
func SplitToken(tok string) (Claims, string, map[string]string, error) {
	var c Claims
	fields := strings.Split(tok, ":")
	extra := map[string]string{}
	claimEnd := 0
	for idx, f := range fields {
		eq := strings.IndexByte(f, '=')
		if eq < 0 {
			return c, "", nil, errors.New("malformed field")
		}
		k, v := f[:eq], f[eq+1:]
		switch k {
		case "URLPrefix":
			b, err := B64.DecodeString(v)
			if err != nil || idx != 0 {
				return c, "", nil, errors.New("bad URLPrefix")
			}
			c.URLPrefix = string(b)
			claimEnd += len(f)
		case "Expires":
			x, err := strconv.ParseInt(v, 10, 64)
			if err != nil {
				return c, "", nil, err
			}
			c.Expires = x
			claimEnd += 1 + len(f)
		case "Tenant":
			x, err := strconv.ParseUint(v, 10, 32)
			if err != nil {
				return c, "", nil, err
			}
			c.Tenant = uint32(x)
			claimEnd += 1 + len(f)
		case "IP":
			c.IP = v
			claimEnd += 1 + len(f)
		default:
			extra[k] = v
		}
	}
	if c.URLPrefix == "" {
		return c, "", nil, errors.New("no URLPrefix")
	}
	return c, tok[:claimEnd], extra, nil
}

// ---------------------------------------------------------------- keys

// Keys holds every key used in the prototype; derived deterministically from a seed so that
// issuer, edge and load generator agree without key files.
type Keys struct {
	HMAC     []byte
	MultiMAC [][]byte // B10, up to 10 domains
	Ed       ed25519.PrivateKey
	EdPub    ed25519.PublicKey
	EC       *ecdsa.PrivateKey
	M44      *mldsa44.PrivateKey
	M44Pub   *mldsa44.PublicKey
	M65      *mldsa65.PrivateKey
	M65Pub   *mldsa65.PublicKey
	// B11 delegated Ed25519 key (per delegation id)
	DelegEd    ed25519.PrivateKey
	DelegEdPub ed25519.PublicKey
	// B12 edge ML-KEM-768 key
	EdgeKEM *mlkem.DecapsulationKey768
}

func drbg(seed uint64, label string, n int) []byte {
	out := make([]byte, 0, n)
	for ctr := uint32(0); len(out) < n; ctr++ {
		h := sha256.New()
		var b [12]byte
		binary.BigEndian.PutUint64(b[:], seed)
		binary.BigEndian.PutUint32(b[8:], ctr)
		h.Write(b[:])
		h.Write([]byte(label))
		out = h.Sum(out)
	}
	return out[:n]
}

func DeriveKeys(seed uint64) *Keys {
	k := &Keys{}
	k.HMAC = drbg(seed, "hmac", 32)
	for j := 0; j < 10; j++ {
		k.MultiMAC = append(k.MultiMAC, drbg(seed, fmt.Sprintf("mmac%d", j), 32))
	}
	k.Ed = ed25519.NewKeyFromSeed(drbg(seed, "ed25519", 32))
	k.EdPub = k.Ed.Public().(ed25519.PublicKey)
	// ECDSA P-256 from a derived scalar (Go's GenerateKey is not deterministic).
	curve := elliptic.P256()
	d := new(big.Int).SetBytes(drbg(seed, "p256", 40))
	d.Mod(d, new(big.Int).Sub(curve.Params().N, big.NewInt(1)))
	d.Add(d, big.NewInt(1))
	x, y := curve.ScalarBaseMult(d.FillBytes(make([]byte, 32)))
	k.EC = &ecdsa.PrivateKey{PublicKey: ecdsa.PublicKey{Curve: curve, X: x, Y: y}, D: d}
	var s32 [32]byte
	copy(s32[:], drbg(seed, "mldsa44", 32))
	k.M44Pub, k.M44 = mldsa44.NewKeyFromSeed(&s32)
	copy(s32[:], drbg(seed, "mldsa65", 32))
	k.M65Pub, k.M65 = mldsa65.NewKeyFromSeed(&s32)
	k.DelegEd = ed25519.NewKeyFromSeed(drbg(seed, "deleg-ed25519", 32))
	k.DelegEdPub = k.DelegEd.Public().(ed25519.PublicKey)
	dk, err := mlkem.NewDecapsulationKey768(drbg(seed, "edge-mlkem768", 64))
	if err != nil {
		panic(err)
	}
	k.EdgeKEM = dk
	return k
}

// ---------------------------------------------------------------- per-token schemes

var ctxToken = []byte("CDN-token")

const (
	B1  = "b1"  // HMAC-SHA256
	B2  = "b2"  // Ed25519
	B3  = "b3"  // ECDSA P-256
	B5  = "b5"  // ML-DSA-44
	B5v = "b5v" // ML-DSA-44 + edge verify cache
	B6  = "b6"  // ML-DSA-65
	B9  = "b9"  // Ed25519 + ML-DSA-44
	B10 = "b10" // multi-MAC (k domains)
	B11 = "b11" // delegated Ed25519
	B12 = "b12" // KEM-wrapped epoch HMAC
)

// SignPerToken returns the full token string for per-token schemes.
func SignPerToken(k *Keys, scheme string, c Claims, aux int) (string, error) {
	enc := c.Enc()
	switch scheme {
	case B1:
		m := hmac.New(sha256.New, k.HMAC)
		m.Write([]byte(enc))
		return enc + ":Sig=" + B64.EncodeToString(m.Sum(nil)), nil
	case B2:
		return enc + ":Sig=" + B64.EncodeToString(ed25519.Sign(k.Ed, ctxMsg(ctxToken, enc))), nil
	case B3:
		h := sha256.Sum256(ctxMsg(ctxToken, enc))
		sig, err := ecdsa.SignASN1(randReader{}, k.EC, h[:])
		if err != nil {
			return "", err
		}
		return enc + ":Sig=" + B64.EncodeToString(sig), nil
	case B5, B5v:
		sig := make([]byte, mldsa44.SignatureSize)
		if err := mldsa44.SignTo(k.M44, []byte(enc), ctxToken, true, sig); err != nil {
			return "", err
		}
		return enc + ":Sig=" + B64.EncodeToString(sig), nil
	case B6:
		sig := make([]byte, mldsa65.SignatureSize)
		if err := mldsa65.SignTo(k.M65, []byte(enc), ctxToken, true, sig); err != nil {
			return "", err
		}
		return enc + ":Sig=" + B64.EncodeToString(sig), nil
	case B9:
		sig := make([]byte, mldsa44.SignatureSize)
		if err := mldsa44.SignTo(k.M44, []byte(enc), ctxToken, true, sig); err != nil {
			return "", err
		}
		ed := ed25519.Sign(k.Ed, ctxMsg(ctxToken, enc))
		return enc + ":Sig=" + B64.EncodeToString(append(ed, sig...)), nil
	case B10:
		kk := aux
		if kk <= 0 {
			kk = 1
		}
		var tags []byte
		for j := 0; j < kk; j++ {
			m := hmac.New(sha256.New, k.MultiMAC[j])
			m.Write([]byte(enc))
			tags = append(tags, m.Sum(nil)[:16]...)
		}
		return enc + ":Sig=" + B64.EncodeToString(tags), nil
	case B11: // sig = deleg_id u32 | Ed25519("CDN-token"||claims)
		sig := binary.BigEndian.AppendUint32(nil, uint32(aux))
		sig = append(sig, ed25519.Sign(k.DelegEd, ctxMsg(ctxToken, enc))...)
		return enc + ":Sig=" + B64.EncodeToString(sig), nil
	case B12: // sig = epoch u32 | HMAC(k_e, claims)
		m := hmac.New(sha256.New, EpochKey(k, uint32(aux)))
		m.Write([]byte(enc))
		return enc + ":Sig=" + B64.EncodeToString(append(binary.BigEndian.AppendUint32(nil, uint32(aux)), m.Sum(nil)...)), nil
	}
	return "", fmt.Errorf("unknown scheme %s", scheme)
}

func ctxMsg(ctx []byte, s string) []byte { return append(append([]byte{}, ctx...), s...) }

type randReader struct{}

func (randReader) Read(p []byte) (int, error) { return cryptoRandRead(p) }

// ---------------------------------------------------------------- B11 delegation cert

// Delegation cert = body(48) || ML-DSA-44 sig (context "EMBER-deleg") over body,
// body = deleg_id u32 | kid u32 | ed_pk[32] | not_after u64.
func MakeDelegCert(k *Keys, id uint32, notAfter int64) []byte {
	body := binary.BigEndian.AppendUint32(nil, id)
	body = binary.BigEndian.AppendUint32(body, 1)
	body = append(body, k.DelegEdPub...)
	body = binary.BigEndian.AppendUint64(body, uint64(notAfter))
	sig := make([]byte, mldsa44.SignatureSize)
	if err := mldsa44.SignTo(k.M44, body, []byte("EMBER-deleg"), true, sig); err != nil {
		panic(err)
	}
	return append(body, sig...)
}

// VerifyDelegCert returns (id, ed_pk, notAfter) if the ML-DSA-44 signature verifies.
func VerifyDelegCert(pub *mldsa44.PublicKey, cert []byte) (uint32, ed25519.PublicKey, int64, error) {
	if len(cert) != 48+mldsa44.SignatureSize {
		return 0, nil, 0, errors.New("bad cert len")
	}
	id := binary.BigEndian.Uint32(cert)
	pk := ed25519.PublicKey(append([]byte{}, cert[8:40]...))
	na := int64(binary.BigEndian.Uint64(cert[40:48]))
	if !mldsa44.Verify(pub, cert[:48], []byte("EMBER-deleg"), cert[48:]) {
		return 0, nil, 0, errors.New("bad cert sig")
	}
	return id, pk, na, nil
}

// ---------------------------------------------------------------- B12 epoch keys

// EpochKey is the issuer-side per-epoch HMAC key k_e.
func EpochKey(k *Keys, e uint32) []byte { return drbg(uint64(e), "b12-epoch"+string(k.HMAC), 32) }

// WrapEpochKey: ML-KEM-768 encapsulation to the edge key, then AES-256-GCM(k_e) under SHA-256(ss|e).
func WrapEpochKey(ek *mlkem.EncapsulationKey768, e uint32, ke []byte) []byte {
	ss, ct := ek.Encapsulate()
	kek := sha256.Sum256(binary.BigEndian.AppendUint32(append([]byte{}, ss...), e))
	blk, _ := aes.NewCipher(kek[:])
	g, _ := cipher.NewGCM(blk)
	nonce := make([]byte, 12)
	out := binary.BigEndian.AppendUint32(nil, e)
	out = append(out, ct...)
	return append(out, g.Seal(nil, nonce, ke, nil)...)
}

func UnwrapEpochKey(dk *mlkem.DecapsulationKey768, w []byte) (uint32, []byte, error) {
	if len(w) < 4+mlkem.CiphertextSize768+16 {
		return 0, nil, errors.New("short wrap")
	}
	e := binary.BigEndian.Uint32(w)
	ss, err := dk.Decapsulate(w[4 : 4+mlkem.CiphertextSize768])
	if err != nil {
		return 0, nil, err
	}
	kek := sha256.Sum256(binary.BigEndian.AppendUint32(append([]byte{}, ss...), e))
	blk, _ := aes.NewCipher(kek[:])
	g, _ := cipher.NewGCM(blk)
	ke, err := g.Open(nil, make([]byte, 12), w[4+mlkem.CiphertextSize768:], nil)
	return e, ke, err
}

// ---------------------------------------------------------------- per-token verify

// Verifier holds edge-side state for the per-token schemes.
type Verifier struct {
	K        *Keys
	DelegPub map[uint32]ed25519.PublicKey // B11: verified delegation certs
	EpochK   map[uint32][]byte            // B12: unwrapped epoch keys
}

func NewVerifier(k *Keys) *Verifier {
	return &Verifier{K: k, DelegPub: map[uint32]ed25519.PublicKey{}, EpochK: map[uint32][]byte{}}
}

// VerifyPerToken checks the authenticator only (policy checks are done by the caller).
func (v *Verifier) VerifyPerToken(scheme, tok string) (Claims, error) {
	i := strings.LastIndex(tok, ":Sig=")
	if i < 0 {
		return Claims{}, errors.New("no Sig")
	}
	body := tok[:i]
	sig, err := B64.DecodeString(tok[i+5:])
	if err != nil {
		return Claims{}, err
	}
	c, enc, extra, err := SplitToken(body)
	if err != nil {
		return c, err
	}
	if len(extra) != 0 {
		return c, errors.New("unknown field")
	}
	ok := false
	switch scheme {
	case B1:
		m := hmac.New(sha256.New, v.K.HMAC)
		m.Write([]byte(enc))
		ok = hmac.Equal(m.Sum(nil), sig)
	case B2:
		ok = ed25519.Verify(v.K.EdPub, ctxMsg(ctxToken, enc), sig)
	case B3:
		h := sha256.Sum256(ctxMsg(ctxToken, enc))
		ok = ecdsa.VerifyASN1(&v.K.EC.PublicKey, h[:], sig)
	case B5, B5v:
		ok = mldsa44.Verify(v.K.M44Pub, []byte(enc), ctxToken, sig)
	case B6:
		ok = mldsa65.Verify(v.K.M65Pub, []byte(enc), ctxToken, sig)
	case B9:
		ok = len(sig) == 64+mldsa44.SignatureSize && ed25519.Verify(v.K.EdPub, ctxMsg(ctxToken, enc), sig[:64]) &&
			mldsa44.Verify(v.K.M44Pub, []byte(enc), ctxToken, sig[64:])
	case B10: // verify domain 0's tag
		m := hmac.New(sha256.New, v.K.MultiMAC[0])
		m.Write([]byte(enc))
		ok = len(sig) >= 16 && hmac.Equal(m.Sum(nil)[:16], sig[:16])
	case B11:
		if len(sig) != 68 {
			return c, errors.New("bad B11 sig len")
		}
		pk, have := v.DelegPub[binary.BigEndian.Uint32(sig)]
		ok = have && ed25519.Verify(pk, ctxMsg(ctxToken, enc), sig[4:])
	case B12:
		if len(sig) != 36 {
			return c, errors.New("bad B12 sig len")
		}
		ke, have := v.EpochK[binary.BigEndian.Uint32(sig)]
		if have {
			m := hmac.New(sha256.New, ke)
			m.Write([]byte(enc))
			ok = hmac.Equal(m.Sum(nil), sig[4:])
		}
	default:
		return c, fmt.Errorf("unknown scheme %s", scheme)
	}
	if !ok {
		return c, errors.New("bad signature")
	}
	return c, nil
}

// ---------------------------------------------------------------- EMBER

// alg byte = signer_id<<4 | (n==32)
const (
	AlgMLDSA44 = 1 << 4
	AlgMLDSA65 = 2 << 4
	AlgSLH128s = 3 << 4
	AlgSLH128f = 4 << 4
	AlgHybrid  = 5 << 4
	AlgEd25519 = 6 << 4
	AlgN32     = 1
)

var ctxRoot = []byte("EMBER-root")

// SignedRoot SR_e = (kid, e, T_start, Δ, N, R, σ).
type SignedRoot struct {
	Alg      uint8
	Kid      uint32
	Epoch    uint32
	TStartMs uint64
	DeltaMs  uint32
	N        uint32
	R        []byte
	Sig      []byte
}

func (s *SignedRoot) Msg() []byte {
	b := append([]byte{}, ctxRoot...)
	b = binary.BigEndian.AppendUint32(b, s.Kid)
	b = binary.BigEndian.AppendUint32(b, s.Epoch)
	b = binary.BigEndian.AppendUint64(b, s.TStartMs)
	b = binary.BigEndian.AppendUint32(b, s.DeltaMs)
	b = binary.BigEndian.AppendUint32(b, s.N)
	return append(b, s.R...)
}

// Marshal: kid|epoch|tstart(8)|delta(4)|N(4)|n(1)|R|sig  (Alg is not on the wire: the edge
// takes the root algorithm from its kid configuration, never from the token).
func (s *SignedRoot) Marshal() []byte {
	b := binary.BigEndian.AppendUint32(nil, s.Kid)
	b = binary.BigEndian.AppendUint32(b, s.Epoch)
	b = binary.BigEndian.AppendUint64(b, s.TStartMs)
	b = binary.BigEndian.AppendUint32(b, s.DeltaMs)
	b = binary.BigEndian.AppendUint32(b, s.N)
	b = append(b, byte(len(s.R)))
	b = append(b, s.R...)
	return append(b, s.Sig...)
}

func UnmarshalRoot(b []byte, alg uint8) (*SignedRoot, error) {
	if len(b) < 25 {
		return nil, errors.New("bad root")
	}
	s := &SignedRoot{Alg: alg, Kid: binary.BigEndian.Uint32(b[0:]), Epoch: binary.BigEndian.Uint32(b[4:]),
		TStartMs: binary.BigEndian.Uint64(b[8:]), DeltaMs: binary.BigEndian.Uint32(b[16:]), N: binary.BigEndian.Uint32(b[20:])}
	n := int(b[24])
	if (n != 16 && n != 32) || len(b) < 25+n {
		return nil, errors.New("short root")
	}
	s.R = append([]byte{}, b[25:25+n]...)
	s.Sig = append([]byte{}, b[25+n:]...)
	return s, nil
}

func SignRoot(k *Keys, s *SignedRoot) {
	switch s.Alg &^ AlgN32 {
	case AlgMLDSA44:
		s.Sig = make([]byte, mldsa44.SignatureSize)
		if err := mldsa44.SignTo(k.M44, s.Msg(), ctxRoot, true, s.Sig); err != nil {
			panic(err)
		}
	case AlgHybrid:
		sig := make([]byte, mldsa44.SignatureSize)
		if err := mldsa44.SignTo(k.M44, s.Msg(), ctxRoot, true, sig); err != nil {
			panic(err)
		}
		s.Sig = append(ed25519.Sign(k.Ed, append(append([]byte{}, ctxRoot...), s.Msg()...)), sig...)
	default:
		panic("root alg not supported in Go prototype")
	}
}

func VerifyRoot(k *Keys, s *SignedRoot) bool { return VerifyRootWith(k.M44Pub, k.EdPub, s) }

// VerifyRootWith verifies SR under the algorithm in s.Alg (from the edge's kid configuration).
func VerifyRootWith(m44 *mldsa44.PublicKey, ed ed25519.PublicKey, s *SignedRoot) bool {
	edMsg := func() []byte { return append(append([]byte{}, ctxRoot...), s.Msg()...) }
	switch s.Alg &^ AlgN32 {
	case AlgMLDSA44:
		return mldsa44.Verify(m44, s.Msg(), ctxRoot, s.Sig)
	case AlgEd25519:
		return len(s.Sig) == 64 && ed25519.Verify(ed, edMsg(), s.Sig)
	case AlgHybrid:
		return len(s.Sig) == 64+mldsa44.SignatureSize && ed25519.Verify(ed, edMsg(), s.Sig[:64]) &&
			mldsa44.Verify(m44, s.Msg(), ctxRoot, s.Sig[64:])
	}
	return false
}

// EmberBlob: ver(1)|alg(1)|kid(4)|epoch(4)|idx(4)|r(16)|path
type EmberBlob struct {
	Alg   uint8
	Kid   uint32
	Epoch uint32
	Idx   uint32
	R     []byte
	Path  []byte
}

func EncodeEmber(c Claims, b EmberBlob) string {
	raw := []byte{1, b.Alg}
	raw = binary.BigEndian.AppendUint32(raw, b.Kid)
	raw = binary.BigEndian.AppendUint32(raw, b.Epoch)
	raw = binary.BigEndian.AppendUint32(raw, b.Idx)
	raw = append(raw, b.R...)
	raw = append(raw, b.Path...)
	return c.Enc() + ":E=" + B64.EncodeToString(raw)
}

// ParseEmber parses a token; returns claims, canonical claims string and blob.
func ParseEmber(tok string) (Claims, string, EmberBlob, error) {
	var b EmberBlob
	i := strings.LastIndex(tok, ":E=")
	if i < 0 {
		return Claims{}, "", b, errors.New("no E")
	}
	c, enc, extra, err := SplitToken(tok[:i])
	if err != nil || len(extra) != 0 {
		return c, "", b, errors.New("bad claims")
	}
	raw, err := B64.DecodeString(tok[i+3:])
	if err != nil || len(raw) < 30 || raw[0] != 1 || raw[1]&0x0E != 0 {
		return c, "", b, errors.New("bad blob")
	}
	b = EmberBlob{Alg: raw[1], Kid: binary.BigEndian.Uint32(raw[2:]), Epoch: binary.BigEndian.Uint32(raw[6:]),
		Idx: binary.BigEndian.Uint32(raw[10:]), R: raw[14:30], Path: raw[30:]}
	return c, enc, b, nil
}

// VerifyEmberPath checks the token's path against a (verified) root.
func VerifyEmberPath(c Claims, enc string, b EmberBlob, root *SignedRoot) bool {
	n := 16
	if b.Alg&AlgN32 != 0 {
		n = 32
	}
	if b.Kid != root.Kid || b.Epoch != root.Epoch || len(b.Path)%n != 0 {
		return false
	}
	leaf := LeafHash(b.Kid, b.Epoch, b.Idx, c.Tenant, b.R, []byte(enc), n)
	got, err := RootFromPath(b.Kid, b.Epoch, b.Idx, root.N, leaf, b.Path, n)
	return err == nil && subtle.ConstantTimeCompare(got, root.R) == 1
}

// IssueEpoch builds an epoch tree over the claims, signs the root and returns tokens.
func IssueEpoch(k *Keys, alg uint8, kid, epoch uint32, tStartMs uint64, deltaMs uint32, cs []Claims, rnd func([]byte)) (*SignedRoot, []string) {
	n := 16
	if alg&AlgN32 != 0 {
		n = 32
	}
	N := len(cs)
	encs := make([]string, N)
	rs := make([][]byte, N)
	leaves := make([][]byte, N)
	for i, c := range cs {
		encs[i] = c.Enc()
		rs[i] = make([]byte, 16)
		rnd(rs[i])
		leaves[i] = LeafHash(kid, epoch, uint32(i), c.Tenant, rs[i], []byte(encs[i]), n)
	}
	R, levels := BuildTree(kid, epoch, leaves, n)
	sr := &SignedRoot{Alg: alg, Kid: kid, Epoch: epoch, TStartMs: tStartMs, DeltaMs: deltaMs, N: uint32(N), R: R}
	SignRoot(k, sr)
	toks := make([]string, N)
	for i := range cs {
		p := bytes.Join(AuthPath(levels, i), nil)
		toks[i] = EncodeEmber(cs[i], EmberBlob{Alg: alg, Kid: kid, Epoch: epoch, Idx: uint32(i), R: rs[i], Path: p})
	}
	return sr, toks
}
